import { Effect, Logger, LogLevel } from "effect";
import type {
	McpClientLogMessage,
	McpClientLogger,
} from "./mcp-client-logger.js";
import type { SafeErrorDiagnostic } from "./error-policy.js";

const levelForMcp = (
	level: LogLevel.LogLevel,
): McpClientLogMessage["level"] => {
	switch (level) {
		case "Debug":
			return "debug";
		case "Warn":
			return "warning";
		case "Error":
		case "Fatal":
			return "error";
		default:
			return "info";
	}
};

/**
 * Emit a bounded diagnostic through Effect's logger. The default Effect
 * logger writes to stderr; the optional MCP logger is an additional sink.
 * Logger failures are deliberately swallowed at this telemetry boundary.
 */
export function logCoreError(
	message: string,
	data?: SafeErrorDiagnostic,
	mcpLogger?: McpClientLogger,
): void {
	try {
		const sink = mcpLogger
			? Logger.make(({ message: loggedMessage, logLevel }) => {
					mcpLogger({
						level: levelForMcp(logLevel),
						logger: "hevy-core",
						data: {
							message: String(loggedMessage),
							...(data ?? {}),
						},
					});
				})
			: undefined;
		const stderr = Logger.make(({ message: loggedMessage }) => {
			if (data === undefined) {
				console.error(String(loggedMessage));
			} else {
				console.error(String(loggedMessage), data);
			}
		});
		const program = Effect.logError(message).pipe(
			Effect.provide(Logger.layer(sink ? [stderr, sink] : [stderr])),
		);
		Effect.runSync(program);
	} catch {
		// Observability is never allowed to change the business outcome.
	}
}

import type { LoggingMessageNotification } from "@modelcontextprotocol/server";
import { createSafeErrorDiagnostic } from "./error-policy.js";
import { logCoreError } from "./core-logger.js";
import type { RuntimeValue } from "./type-predicates.js";

export type McpClientLogMessage = LoggingMessageNotification["params"];
export type McpClientLogger = (message: McpClientLogMessage) => void;

interface LoggingServer {
	isConnected(): boolean;
	sendLoggingMessage(message: McpClientLogMessage): Promise<void>;
}

const SEND_FAILURE_MESSAGE =
	"Failed to send structured log message to MCP client";
const DISCONNECTED_MESSAGE =
	"Skipped structured MCP client log because the server is not connected";

/**
 * Create a best-effort, fire-and-forget logger for an MCP server connection.
 * Logging failures are reported to stderr and never escape into tool behavior.
 */
export function createMcpClientLogger(server: LoggingServer): McpClientLogger {
	return (message) => {
		try {
			if (!server.isConnected()) {
				logCoreError(DISCONNECTED_MESSAGE);
				return;
			}

			void server.sendLoggingMessage(message).catch((error: RuntimeValue) => {
				logCoreError(SEND_FAILURE_MESSAGE, createSafeErrorDiagnostic(error));
			});
		} catch (error) {
			logCoreError(SEND_FAILURE_MESSAGE, createSafeErrorDiagnostic(error));
		}
	};
}

import type { McpServer } from "@modelcontextprotocol/server";
import { z } from "zod";
import { utcSecondTimestamp } from "../utils/schemas.js";
import { memoizeObservationScope, type ToolObserver } from "../observation.js";
import { bucketCount } from "../utils/result-telemetry.js";
import { resolveErrorPolicy } from "../utils/error-policy.js";
import { isString } from "../utils/type-predicates.js";
import { logCoreError } from "../utils/core-logger.js";

type PromptResult = {
	messages: Array<{
		role: "user" | "assistant";
		content: { type: "text"; text: string };
	}>;
};

function withPromptObservation<TArgs extends object>(
	name: string,
	observer: ToolObserver | undefined,
	handler: (args: TArgs) => Promise<PromptResult> | PromptResult,
) {
	return async (args: TArgs): Promise<PromptResult> => {
		const startedAt = Date.now();
		let scope;
		try {
			const argumentKeys = Object.keys(args).filter(
				(key): key is "routine_id" => key === "routine_id",
			);
			const routineId =
				"routine_id" in args && isString(args.routine_id)
					? args.routine_id
					: undefined;
			scope = memoizeObservationScope(
				observer?.start({
					name,
					kind: "prompt",
					argumentKeys,
					argumentPresence: routineId ? { routine_id: true } : {},
					argumentKeyCountBucket: bucketCount(Object.keys(args).length),
				}),
			);
		} catch {
			scope = undefined;
		}

		try {
			let handlerPromise: Promise<PromptResult> | undefined;
			const invoke = () => {
				handlerPromise ??= Promise.resolve(handler(args));
				return handlerPromise;
			};
			let result: PromptResult;
			try {
				result = await (scope ? scope.run(invoke) : invoke());
			} catch (observerError) {
				// A scope may reject after invoking the handler. Reuse the
				// memoized handler promise rather than executing a prompt twice.
				if (!handlerPromise) throw observerError;
				result = await handlerPromise;
			}
			void scope?.finish({
				outcome: "success",
				durationMs: Date.now() - startedAt,
				result: {
					isError: false,
					hasStructuredContent: false,
					contentCountBucket: bucketCount(result.messages.length),
				},
			});
			return result;
		} catch (error) {
			const policy = resolveErrorPolicy(error, "MCP prompt failed");
			void scope?.finish({
				outcome: "thrown_error",
				durationMs: Date.now() - startedAt,
				errorType: policy.type,
				error: policy.diagnostic,
			});
			logCoreError("MCP prompt failure", policy.diagnostic);
			throw error;
		}
	};
}

/** Register guided workout workflow prompts. */
export function registerWorkoutPrompts(
	server: McpServer,
	observer?: ToolObserver,
) {
	server.registerPrompt(
		"analyze-workout-progress",
		{
			title: "Analyze Workout Progress",
			description: "Analyze recent workout and body-measurement trends.",
			argsSchema: z.object({
				weeks: z.coerce
					.number()
					.int()
					.min(1)
					.max(12)
					.default(4)
					.optional()
					.describe("Number of recent weeks to analyze (1-12)."),
			}),
		},
		withPromptObservation(
			"analyze-workout-progress",
			observer,
			({ weeks = 4 }) => ({
				messages: [
					{
						role: "user",
						content: {
							type: "text",
							text: [
								`Analyze my workout progress over the last ${weeks} weeks.`,
								"Call get-training-summary with the requested weeks; it combines recent workouts and body measurements into one compact evidence set.",
								"Use the returned period, workout frequency, volume, exercise variety, session list, and measurement trend fields rather than issuing separate count and pagination calls.",
								"Base the analysis on retrieved evidence and discuss workout frequency, training volume, exercise variety, consistency, and body-measurement trends.",
								"Distinguish observations from suggestions, note missing or limited data, and do not make unsupported claims or medical conclusions.",
							].join("\n"),
						},
					},
				],
			}),
		),
	);

	server.registerPrompt(
		"create-workout-from-routine",
		{
			title: "Create Workout From Routine",
			description: "Create a completed workout from an existing routine.",
			argsSchema: z.object({
				routine_id: z
					.string()
					.min(1)
					.optional()
					.describe("Routine ID to use as a guide."),
				start_time: utcSecondTimestamp
					.optional()
					.describe("Workout start time in UTC as YYYY-MM-DDTHH:mm:ssZ."),
			}),
		},
		withPromptObservation(
			"create-workout-from-routine",
			observer,
			({ routine_id, start_time }) => ({
				messages: [
					{
						role: "user",
						content: {
							type: "text",
							text:
								routine_id && start_time
									? [
											`Create a workout from routine ${routine_id}, starting at ${start_time}.`,
											[
												"First call get-routine with the routine_id and map supported plan fields:",
												"routine title to workout title, plus each exercise_template_id, superset_id, exercise notes, and set type.",
											].join(" "),
											[
												"Do not copy routine-only rest_seconds or rep_range fields into",
												"create-workout.",
											].join(" "),
											[
												"Before calling create-workout, confirm or collect the user's actual completed set data for every set,",
												"including applicable weight_kg, reps, distance_meters, duration_seconds, rpe, or custom_metric values.",
											].join(" "),
											[
												"Also collect the required end_time in strict UTC YYYY-MM-DDTHH:mm:ssZ format and confirm",
												"any other missing required workout fields.",
											].join(" "),
											[
												"Never invent completion data. If the actual results or end_time are unavailable, ask the user for them",
												"instead of creating the workout.",
											].join(" "),
											"Once confirmed, call create-workout with only fields supported by that tool.",
										].join("\n")
									: "Provide a routine_id and start_time to generate the full prompt.",
						},
					},
				],
			}),
		),
	);
}

import { Cache, Effect, Option } from "effect";
import type { HevyRequestOptions } from "@hevy-mcp/hevy-client";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import type {
	CacheObservationMetadata,
	CacheObservationScope,
	CacheObservationState,
	CacheObserver,
} from "./cache.js";
import { bucketCount } from "./result-telemetry.js";

export const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
export const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
export const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;
const EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE = 100;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

type TemplateListAllError = Effect.Error<
	ReturnType<TemplatesListAllOperation["effect"]>
>;

export type ExerciseTemplateCatalogCache = Cache.Cache<
	string,
	ExerciseTemplate[],
	TemplateListAllError
>;

export interface ExerciseTemplateCatalog {
	/**
	 * Effect-first catalog access for MCP resource and tool handlers.
	 *
	 * The server owns the cache passed to this catalog. Keeping this program
	 * Effect-valued lets the request handler decide where the one Promise
	 * collapse belongs.
	 */
	effect(
		options?: ExerciseTemplateCatalogOptions,
	): Effect.Effect<ExerciseTemplate[], TemplateListAllError>;
	/**
	 * Promise compatibility for callers that have not moved to the handler
	 * Effect boundary yet.
	 */
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
}

type CatalogOperations = {
	readonly templates?: {
		readonly listAll?: Pick<TemplatesListAllOperation, "effect">;
	};
};

function startObservation(
	observer: CacheObserver | undefined,
	state: CacheObservationState,
) {
	try {
		return observer?.start({ state });
	} catch {
		return undefined;
	}
}

function finishObservation(
	scope: CacheObservationScope | void,
	metadata?: CacheObservationMetadata,
): void {
	try {
		scope?.finish(metadata);
	} catch {
		// Cache observation is best-effort and cannot affect cache behavior.
	}
}

function notifyRefreshed(
	options: ExerciseTemplateCatalogOptions,
	catalog: ExerciseTemplate[],
	reason: ExerciseTemplateCatalogRefreshReason,
): void {
	try {
		options.onRefreshed?.(catalog, reason);
	} catch {
		// Cache callbacks are best-effort and cannot affect catalog behavior.
	}
}

function catalogPageCount(catalog: readonly ExerciseTemplate[]): number {
	const pages = (
		catalog as ExerciseTemplate[] & {
			readonly pageCount?: number;
		}
	).pageCount;
	if (pages !== undefined) return pages;
	return Math.max(
		1,
		Math.ceil(catalog.length / EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE),
	);
}

/**
 * Build the catalog facade around one server-owned Effect Cache.
 *
 * `cache` is deliberately supplied by the server rather than constructed
 * here. This keeps cache lifetime at server/process scope instead of making it
 * request-local in `createToolRuntime` or `forExecution`.
 */
